{"id": "8d4d37e2-b024-4af6-9ab4-6d24898f711b:ambient-1-0", "장면": 1, "종류": "함께 나눈 말", "당사자": "준", "함께 있던 사람": ["준", "채연"], "내용": "준: 이거 네 거잖아. 안 먹어?"}
{"id": "8d4d37e2-b024-4af6-9ab4-6d24898f711b:ambient-1-1", "장면": 1, "종류": "함께 나눈 말", "당사자": "채연", "함께 있던 사람": ["준", "채연"], "내용": "채연: 배 안 고파. 너 먹어."}
{"id": "8d4d37e2-b024-4af6-9ab4-6d24898f711b:ambient-1-2", "장면": 1, "종류": "함께 나눈 말", "당사자": "준", "함께 있던 사람": ["준", "채연"], "내용": "준: …이따 배고프면 말해."}
